Now we again want to collect the contribution coming from the singularity of $\zeta(u)^z$ at $u=1/q$ to evaluate the above integral. We shift the contour $|u|=r$ to a bigger circle $|u|=1/q+\widetilde{\eta}$ with a different choice of $\widetilde{\eta}$ here (not the same choice for $\eta$ in Proposition \ref{la}) and with $|z|\leqslant q^2-\delta$. Since the region of absolute convergence for $\widetilde{F_z}(u)$ here is $\widetilde{\mathcal{R}}$, we have a different set of constraints on $\widetilde{\eta}$ than before. Here we get for $\widetilde{\eta}$, $|zu^2|\leqslant (q^{-1}+\widetilde{\eta})^2(q^2-\delta)\leqslant 1$ and $|u|=1/q+\widetilde{\eta}<q^{-\frac{1}{2}}$. This shows taking any $0<\widetilde{\eta} <\min\{1/\sqrt{q^2-\delta}-1/q,1/\sqrt{q}-1/q \}$ suffices. We then plan to use Lemma \ref{l3} to evaluate the integral in (\ref{lg}) with, $\widetilde{\eta}=\min\{1/\sqrt{q^2-\delta}-1/q,1/\sqrt{q}-1/q \}/2$ for $|z|\leqslant q^2-\delta$ just as we did in the proof of Proposition \ref{la}. \\
\begin{remark}
$F_z(u)$ was absolutely convergent in $\mathcal{R}$ which gave us the appropriate choice for $\eta$. All the calculations are identical here with $\widetilde{F_z}$ instead of $F_z$. The main difference is, here we have $|z|\leqslant q^2-\delta$ instead of $|z|\leqslant q-\epsilon$. Earlier ${F}_z\left(\frac{1}{q}\right)$ had a pole at $z=q,q^2,\ldots$ but we got rid of the $z=q$ pole here. This is what essentially allows us to take $|z|\leqslant q^2-\delta.$
\end{remark}
We therefore get
\begin{align}
\nonumber
\widetilde{M}_z(n) &= \dfrac{1}{2\pi i}\displaystyle\int\limits_{\{|u|=\frac{1}{q}+\widetilde{\eta\}}\cup\widetilde{\mathcal{H}'}} \zeta(u)^z\widetilde{F}_z(u)\dfrac{du}{u^{n+1}}\\
\nonumber
&=\widetilde{F}_z\left(\dfrac{1}{q}\right)q^n n^{z-1} \left( \dfrac{1}{\Gamma(z)}+O_{\delta}\left(\dfrac{1}{n}\right)\right)\\
\nonumber
&=q^nn^{z-1}\left(zh(z)+ O_{\delta}\left(\dfrac{1}{n}\right) \right),
\end{align}
where 
$$h(z)=\dfrac{1}{z}\widetilde{F}_z\left(\dfrac{1}{q}\right)\dfrac{1}{\Gamma(z)}=\dfrac{1}{\Gamma(z+1)}\left( 1-\dfrac{1}{q}\right)^{qz}\displaystyle\prod\limits_{p\in\mathcal{P}_{\geqslant 2}}\left(1-\frac{z}{q^{deg(p)}}\right)^{-1}\left( 1-\frac{1}{q^{deg(p)}}\right)^z.$$
Also we have $h(z)=\frac{1}{\Gamma(z+1)}\widetilde{F}_z\left(\frac{1}{q}\right)$. Since, $\widetilde{F}_z\left(\frac{1}{q}\right)$ is analytic in $|z|<q^2$, so is $h$.

\label{lm}
\label{Proof of Lemma 4.4}
By Lemma \ref{l11} we have that
\begin{equation}\label{nw}
N'(n+j-k,j)=\dfrac{q^{n+j-k}}{n+j-k}\Bigg \{Q_j(\log (n+j-k))+ O \left( \dfrac{(\log (n+j-k))^j}{j!(n+j-k)}\right) \Bigg \}.
\end{equation}
We observe $n-k\geqslant n\left(1-\frac{1}{B}\right)\to\infty$ as $n\to\infty$. We also note if $E_1=\frac{(\log (n-k))^{j+1}}{j!(n-k)^2}$ and $E_2=\frac{(\log (n+j-k))^j}{j!(n+j-k)^2}$ then as $n\to\infty$
\begin{align}
\nonumber
\dfrac{E_2}{E_1} &= \dfrac{1}{(\log (n-k))}\left (\dfrac{\log (n+j-k)}{\log (n-k)} \right)^j \dfrac{(n-k)^2}{(n+j-k)^2}\\
\nonumber
&\leqslant\left( 1+ \dfrac{\log\left(1+\dfrac{j}{n-k}\right)}{\log(n-k)}\right)^j\dfrac{1}{(\log(n-k))}\to 0\\
\nonumber
&\implies E_2=o(E_1),
\end{align}
where we have at the second step the term inside the bracket is bounded, because $\frac{j}{n-k}\leqslant \frac{eq\log(n-k)}{(n-k)}\to 0$ and hence for $n$ large enough it is bounded by $(1+\log 2/\log(n-k))^{eq\log(n-k)} \leqslant e^{eq\log 2}=2^{eq}$. Thus from \eqref{nw} we arrive at
\begin{equation}\label{nw1}
    N'(n+j-k,j)=q^{n+j-k}\left \{\dfrac{Q_j(\log (n+j-k))}{n+j-k}+ O \left( E_1\right)\right \}
\end{equation}
We show at a small cost it is possible to replace $\frac{Q_j(\log (n+j-k))}{n+j-k}$ by $\frac{Q_j(\log (n-k))}{n-k}$.
We use mean value theorem to study the error.\\
Let $F(x):=\frac{Q_j(\log x)}{x}$ which is a regular function if $x>0$. The difference caused by this replacement
$$D=\dfrac{Q_j(\log (n+j-k))}{n+j-k}-\dfrac{Q_j(\log (n-k)}{n-k}=F(n+j-k)-F(n-k).$$
By mean value theorem one can pick $y\in (n-k,n+j-k)$ such that
$$D=jF'(y)=j\dfrac{Q_j'(\log y)-Q_j(\log y)}{y^2}=\dfrac{j}{y^2}Q_j'(\log y)-\dfrac{j}{y^2}Q_j(\log y)=F_1+F_2.$$
Therefore \eqref{nw1} implies
\begin{equation}\label{nw2}
     N'(n+j-k,j)=q^{n+j-k}\left \{\frac{Q_j(\log (n-k))}{n-k}+ F_1+F_2+O \left( E_1\right)\right \}
\end{equation}
We apply Lemma \ref{l12}  with the choice $X=\log y$. We note from the hypothesis that $j\leqslant eqY \leqslant eq\log y$ and $y>n-k$, so that we must have $X=\log y\to\infty$ with $n$. Using this observation, we upper bound the first term of $F_1$ which gives
$F_1=\frac{j}{y^2}Q_j'(\log y)\ll \frac{j}{y^2} \frac{(\log(n+j-k))^{j-2}}{(j-2)!}.$ Thus we obtain\\
\begin{align}
\nonumber
\dfrac{F_1}{E_1} &= \dfrac{(n-k)^2j!}{(\log(n-k))^{j+1}} \dfrac{j}{y^2} \dfrac{(\log(n+j-k))^{j-2}}{(j-2)!}\\
\nonumber
&\leqslant\left(\dfrac{\log(n+j-k)}{\log(n-k)}\right)^{j-2} \dfrac{j^2(j-1)}{(\log(n-k))^3}\\
\nonumber
&\ll 1,
\end{align}
since $j\leqslant eq \log(n-k)$ and $y>n-k.$
Hence $F_1=O(E_1)$ and likewise from Lemma \ref{l12} one can show
$|F_2|=\frac{j}{y^2}Q_j(\log y)\ll \frac{j(\log(n+j-k))^{j-1}}{y^2(j-1)!}.$\\
Thus we infer
\begin{align}
\nonumber
\dfrac{|F_2|}{E_1} &= \dfrac{j!(n-k)^2}{(\log(n-k))^{j+1}}\dfrac{j(\log(n+j-k))^{j-1}}{y^2(j-1)!}\\
\nonumber
&\leqslant \left( \dfrac{\log(n+j-k)}{\log(n-k)}\right)^{j-1}\dfrac{j^2}{(\log(n-k))^2}\\
\nonumber
&\ll 1.
\end{align}
The proof is now complete once we plug $F_1+F_2=O(E_1)$ in \eqref{nw2}.
